<script>
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {listDevices} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let loading=true;let items=[];let limit=1;
 onMount(async()=>{const r=await listDevices();if(r.ok){items=r.data.devices||[];limit=r.data.limit||1}else notify(r.error||'Не удалось загрузить устройства','error');loading=false});
</script>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE</div><h1 class="page-title">Devices</h1><p class="page-desc">Подключённые Android-телефоны и их агенты Yevqo.</p></div><Button variant="primary" on:click={()=>goto('/')}>Как подключить устройство</Button></div>
<div class="summary"><div><strong>{items.length} / {limit}</strong><span>Телефонов подключено</span></div><div><strong>{items.filter(x=>x.status==='online').length}</strong><span>Сейчас онлайн</span></div></div>
{#if items.length>=limit}<div class="limit-notice"><strong>Лимит подключений достигнут</strong><span>Бесплатный тариф включает один телефон. Чтобы освободить слот, сначала остановите Agent на старом телефоне, затем откройте его карточку и нажмите «Отвязать». После этого подключите новый телефон.</span></div>{/if}
{#if loading}<div class="empty">Загрузка устройств…</div>{:else if !items.length}<div class="empty"><p>Устройств пока нет</p><p>Подключите Android Agent через Termux, чтобы начать работу.</p><div class="actions"><Button variant="primary" on:click={()=>goto('/')}>Инструкция по подключению</Button></div></div>{:else}
<div class="device-list">{#each items as d (d.id)}<button class="device-row" on:click={()=>goto('/devices/'+d.id)}><span class="device-icon">▣</span><span class="device-main"><strong>{d.hostname||d.device_id?.slice(0,8)||'Android host'}</strong><small>{d.device_id} · Agent {d.agent_version||'—'}</small></span><span class="device-ip">{d.tailscale_ip||'No Tailscale IP'}</span><span class="device-state"><StatusDot status={d.status}/>{d.status==='online'?'Online':'Offline'}</span><span class="arrow">→</span></button>{/each}</div>{/if}
<style>
.eyebrow{font-size:9px;font-weight:700;letter-spacing:.14em;color:#818cf8;margin-bottom:7px}.summary{display:flex;gap:10px;margin-bottom:14px}.summary>div{display:flex;align-items:baseline;gap:8px;padding:12px 15px;background:#101727;border:1px solid #253149;border-radius:10px}.summary strong{font-size:18px}.summary span{font-size:10px;color:#64748b}.device-list{border:1px solid #253149;border-radius:12px;overflow:hidden;background:#101727}.device-row{width:100%;display:flex;align-items:center;gap:13px;padding:13px 15px;background:transparent;border:0;border-bottom:1px solid #1e293b;text-align:left;color:#f1f5f9}.device-row:last-child{border:0}.device-row:hover{background:#172136}.device-icon{width:31px;height:31px;display:grid;place-items:center;border-radius:8px;background:#1b2740;color:#a5b4fc}.device-main{display:flex;flex-direction:column;flex:1;min-width:0}.device-main strong{font-size:11px}.device-main small{font:9px 'JetBrains Mono',monospace;color:#64748b;overflow:hidden;text-overflow:ellipsis}.device-ip,.device-state{font-size:10px;color:#94a3b8}.device-state{display:flex;align-items:center;gap:7px}.arrow{color:#64748b}.actions{margin-top:16px}.limit-notice{display:flex;flex-direction:column;gap:5px;margin:0 0 14px;padding:12px 14px;border:1px solid #66522c;background:#2b2418;border-radius:10px;color:#f3d69b;font-size:11px}.limit-notice span{color:#b9a77f;font-size:10px;line-height:1.5}@media(max-width:650px){.device-row{gap:9px}.device-ip{display:none}.device-main small{max-width:180px}.page-header{align-items:stretch}}
</style>